    lines = [ln.strip() for ln in str(err).splitlines() if ln.strip()]
    noise = ("Warning: Permanently added", "Connection closed", "sftp>", "Connected to", "Couldn't read packet")
    real = [ln for ln in lines if not ln.startswith(noise)]
